def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(
        r"\d+|[A-Z][0-9]+|[A-Z]+|<>|<=|>=|[^\s]"
    )
    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "neg": 3,
        ":": 4,
    }

    def parse(formula):
        nodes = []
        operators = []
        argument_counts = []
        expect_operand = True

        def reduce_operator():
            op = operators.pop()
            if op == "neg":
                nodes.append(("neg", nodes.pop()))
            else:
                right = nodes.pop()
                left = nodes.pop()
                nodes.append((op, left, right))

        for match in token_pattern.finditer(formula):
            token = match.group()

            if token[0].isdigit():
                nodes.append(("num", int(token)))
                expect_operand = False
            elif token in functions:
                operators.append(token)
                expect_operand = True
            elif token[0].isalpha():
                nodes.append(("ref", token))
                expect_operand = False
            elif token == "(":
                operators.append("(")
                argument_counts.append(1)
                expect_operand = True
            elif token == ",":
                while operators[-1] != "(":
                    reduce_operator()
                argument_counts[-1] += 1
                expect_operand = True
            elif token == ")":
                while operators[-1] != "(":
                    reduce_operator()
                operators.pop()
                count = argument_counts.pop()
                if operators and operators[-1] in functions:
                    name = operators.pop()
                    args = tuple(nodes[-count:])
                    del nodes[-count:]
                    nodes.append((name, args))
                expect_operand = False
            else:
                op = "neg" if token == "-" and expect_operand else token
                while operators and operators[-1] != "(":
                    previous = precedence[operators[-1]]
                    current = precedence[op]
                    if previous < current or (
                        previous == current and op == "neg"
                    ):
                        break
                    reduce_operator()
                operators.append(op)
                expect_operand = True

        while operators:
            reduce_operator()
        return nodes[0]

    def expanded_arguments(args):
        for node in args:
            if node[0] != ":":
                yield node
                continue

            first = node[1][1]
            last = node[2][1]
            col1, col2 = sorted((ord(first[0]), ord(last[0])))
            row1, row2 = sorted((int(first[1:]), int(last[1:])))

            for row in range(row1, row2 + 1):
                for col in range(col1, col2 + 1):
                    name = chr(col) + str(row)
                    if name in cells:
                        yield ("ref", name)

    memo = {}
    active = set()

    for root in cells:
        if root in memo:
            continue

        work = [("cell", root)]
        values = []

        while work:
            task = work.pop()
            action = task[0]

            if action == "cell":
                name = task[1]
                if name in memo:
                    values.append(memo[name])
                elif name not in cells:
                    values.append(0)
                elif name in active:
                    values.append("#CYCLE!")
                else:
                    active.add(name)
                    content = cells[name].strip()
                    work.append(("finish_cell", name))
                    if content.startswith("="):
                        work.append(("eval", parse(content[1:])))
                    else:
                        values.append(int(content))

            elif action == "finish_cell":
                name = task[1]
                memo[name] = values[-1]
                active.remove(name)

            elif action == "eval":
                node = task[1]
                op = node[0]

                if op == "num":
                    values.append(node[1])
                elif op == "ref":
                    work.append(("cell", node[1]))
                elif op == "neg":
                    work.append(("negate",))
                    work.append(("eval", node[1]))
                elif op == "IF":
                    args = node[1]
                    work.append(("choose", args[1], args[2]))
                    work.append(("eval", args[0]))
                elif op in ("SUM", "MIN", "MAX"):
                    frame = [
                        op,
                        expanded_arguments(node[1]),
                        0 if op == "SUM" else None,
                    ]
                    work.append(("aggregate_next", frame))
                else:
                    work.append(("binary_left", op, node[2]))
                    work.append(("eval", node[1]))

            elif action == "negate":
                value = values.pop()
                values.append(value if isinstance(value, str) else -value)

            elif action == "choose":
                condition = values.pop()
                if isinstance(condition, str):
                    values.append(condition)
                else:
                    work.append(("eval", task[1] if condition else task[2]))

            elif action == "binary_left":
                left = values.pop()
                if isinstance(left, str):
                    values.append(left)
                else:
                    work.append(("binary_right", task[1], left))
                    work.append(("eval", task[2]))

            elif action == "binary_right":
                right = values.pop()
                if isinstance(right, str):
                    values.append(right)
                    continue

                op, left = task[1], task[2]
                if op == "+":
                    result = left + right
                elif op == "-":
                    result = left - right
                elif op == "*":
                    result = left * right
                elif op == "/":
                    if right == 0:
                        result = "#DIV/0!"
                    else:
                        result = abs(left) // abs(right)
                        if (left < 0) != (right < 0):
                            result = -result
                elif op == "=":
                    result = left == right
                elif op == "<>":
                    result = left != right
                elif op == "<":
                    result = left < right
                elif op == "<=":
                    result = left <= right
                elif op == ">":
                    result = left > right
                else:
                    result = left >= right
                values.append(result)

            elif action == "aggregate_next":
                frame = task[1]
                node = next(frame[1], None)
                if node is None:
                    values.append(0 if frame[2] is None else frame[2])
                else:
                    work.append(("aggregate_value", frame))
                    work.append(("eval", node))

            elif action == "aggregate_value":
                frame = task[1]
                value = values.pop()
                if isinstance(value, str):
                    values.append(value)
                    continue

                if frame[0] == "SUM":
                    frame[2] += value
                elif frame[2] is None:
                    frame[2] = value
                elif frame[0] == "MIN":
                    frame[2] = min(frame[2], value)
                else:
                    frame[2] = max(frame[2], value)
                work.append(("aggregate_next", frame))

    return {name: memo[name] for name in cells}
